"""Central role-prompt bank for the OR-Path domain teams.

Every domain collaboration module consumes its six role prompts from
this single bank so the ten legacy 900-line clone modules can be
compressed into thin cartridge-driven shims (Plan 2.4).

Prompts are stored verbatim and resolved at assembly time by
``orpath.agents.cartridges.build_team_namespace``.
"""

from __future__ import annotations

# Domain -> {variable name: role prompt text} (byte-identical to the
# original per-domain module definitions).
